const fs = require('fs');
const path = require('path');

function scanFiles(dir) {
    const files = fs.readdirSync(dir).filter(file => file.endsWith('.js'));
    return files.map(file => {
        const filePath = path.join(dir, file);
        const content = fs.readFileSync(filePath, 'utf8');
        const lines = content.split('\n');
        const hasShebang = lines[0].startsWith('#!');
        let docstring = '';
        let inDocBlock = false;

        for (const line of lines) {
            if (line.startsWith('/**')) {
                inDocBlock = true;
                continue;
            }
            if (inDocBlock && line.startsWith('*/')) {
                inDocBlock = false;
                break;
            }
            if (inDocBlock) {
                const descLine = line.replace(/^\s*\*/, '').trim();
                if (descLine) {
                    docstring = descLine;
                    break;
                }
            }
            if (line.startsWith('//') && !docstring) {
                docstring = line.replace(/^\s*\/\/\s*/, '').trim();
                break;
            }
        }

        const owner = lines.find(line => line.includes('# owner:'))?.split(':')[1]?.trim();
        const version = lines.find(line => line.includes('# version:'))?.split(':')[1]?.trim();
        const hasCLI = content.includes('process.argv');
        return {
            name: file,
            path: filePath,
            description: docstring,
            owner,
            version,
            hasCLI
        };
    });
}

function generateIndex() {
    const tools = scanFiles(path.join(__dirname));
    fs.writeFileSync(path.join(__dirname, '.compiled-state', 'tool-index.json'), JSON.stringify(tools, null, 2));
}

function queryIndex(keyword) {
    const tools = JSON.parse(fs.readFileSync(path.join(__dirname, '.compiled-state', 'tool-index.json'), 'utf8'));
    return tools.filter(tool =>
        tool.description.toLowerCase().includes(keyword.toLowerCase())
