      droppedPositions.push({
        positionId,
        originalSupport: entry.clusterCount,
        supportRatio,
        statuses: Array.from(entry.statuses),
        reason: "Below carry-over threshold"
      });
    }
  });

  // Step 3: Sort by amplified weight (descending)
  amplifiedPositions.sort((a, b) => b.amplifiedWeight - a.amplifiedWeight);

  return {
    amplifiedPositions,
    droppedPositions,
    diversityScore: computeDiversityScore(amplifiedPositions),
    minorityReport: generateMinorityReport(clusterOutputs, amplifiedPositions, droppedPositions)
  };
}

/**
 * Computes diversity score (0-1) based on position distribution.
 * @param {Array} positions - Amplified positions
 * @returns {number} - Diversity score
 */
function computeDiversityScore(positions) {
  if (positions.length === 0) return 0;

  const supportRatios = positions.map(p => p.supportRatio);
  const meanSupport = supportRatios.reduce((sum, val) => sum + val, 0) / supportRatios.length;
  const variance = supportRatios.reduce((sum, val) => sum + Math.pow(val - meanSupport, 2), 0) / supportRatios.length;

  // Normalize to 0-1 range (higher variance = more diversity)
  return 1 - Math.min(1, Math.sqrt(variance) / 0.5);
}

/**
 * Generates minority report with amplification statistics.
 * @param {Array} clusterOutputs - Original cluster outputs
 * @param {Array} amplifiedPositions - Amplified positions
 * @param {Array} droppedPositions - Dropped positions
 * @returns {string} - Formatted report
 */
function generateMinorityReport(clusterOutputs, amplifiedPositions, droppedPositions) {
  const totalPositions = amplifiedPositions.length + droppedPositions.length;
  const minorityPositions = amplifiedPositions.filter(p => p.isMinority).length;
  const bedrockPositions = amplifiedPositions.filter(p => p.statuses.includes('BEDROCK')).length;

  return `
MINORITY AMPLIFICATION REPORT
=============================
Clusters processed: ${clusterOutputs.length}
Total positions: ${totalPositions}
Amplified positions: ${amplifiedPositions.length} (${Math.round((amplifiedPositions.length / totalPositions) * 100)}%)
Dropped positions: ${droppedPositions.length} (${Math.round((droppedPositions.length / totalPositions) * 100)}%)
Minority positions amplified: ${minorityPositions} (${Math.round((minorityPositions / amplifiedPositions.length) * 100)}%)
BEDROCK positions preserved: ${bedrockPositions} (${Math.round((bedrockPositions / amplifiedPositions.length) * 100)}%)
Diversity score: ${computeDiversityScore(amplifiedPositions).toFixed(3)}
  `.trim();
}

module.exports = {
  amplifyMinorities,
  computeDiversityScore,
  generateMinorityReport
};

